import React from "react";
import {
  AbsoluteFill,
  Audio,
  Easing,
  Img,
  OffthreadVideo,
  Sequence,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
} from "remotion";
import { loadFont as loadSerif } from "@remotion/google-fonts/PlayfairDisplay";
import { loadFont as loadSans } from "@remotion/google-fonts/DMSans";
import { CAPS } from "./captions";

export const MI_FPS = 30;
export const MI_VIDEO_FRAMES = 1804; // 60,13 s do corte
export const MI_FRAMES = 1860; // + cartela final

const { fontFamily: SERIF } = loadSerif("normal", { weights: ["500", "600"], subsets: ["latin"] });
loadSerif("italic", { weights: ["500"], subsets: ["latin"] });
const { fontFamily: SANS } = loadSans("normal", { weights: ["500", "700"], subsets: ["latin"] });

const C = {
  bg: "#EAF3FB",
  bg2: "#D9E9F7",
  line: "#B9D4EC",
  blue: "#4A8FCB",
  deep: "#2F6FAE",
  navy: "#16324F",
  mute: "#5C7A96",
  white: "#FFFFFF",
  warm: "#F0B45C",
};

const PANEL_TOP = 960;
const SHIFT = 120; // conteúdo do painel desce junto
const f = (s: number) => Math.round(s * MI_FPS);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** 0→1 com mola suave a partir de `s` segundos */
const useSp = (s: number, damping = 200, mass = 0.7) => {
  const frame = useCurrentFrame();
  return spring({ frame: frame - f(s), fps: MI_FPS, config: { damping, mass, stiffness: 140 } });
};
/** 0→1 linear suavizado entre dois tempos */
const useRamp = (a: number, b: number) => {
  const frame = useCurrentFrame();
  return interpolate(frame, [f(a), f(b)], [0, 1], { ...clamp, easing: Easing.inOut(Easing.cubic) });
};
/** visibilidade de saída: 1 até `out`, cai a 0 em 6 quadros */
const useOut = (out: number) => {
  const frame = useCurrentFrame();
  return interpolate(frame, [f(out) - 6, f(out)], [1, 0], clamp);
};

// ───────── texto que entra por máscara ─────────
const Reveal: React.FC<{
  at: number;
  out?: number;
  style?: React.CSSProperties;
  children: React.ReactNode;
}> = ({ at, out, style, children }) => {
  const p = useSp(at);
  const o = useOut(out ?? 9999);
  return (
    <div style={{ overflow: "hidden", paddingBottom: "0.16em", ...style }}>
      <div style={{ transform: `translateY(${(1 - p) * 115}%)`, opacity: o }}>{children}</div>
    </div>
  );
};

const serif = (size: number, italic = false): React.CSSProperties => ({
  fontFamily: SERIF,
  fontSize: size,
  fontWeight: 500,
  fontStyle: italic ? "italic" : "normal",
  color: C.navy,
  lineHeight: 1.08,
  letterSpacing: "-0.01em",
});
const sans = (size: number, weight = 500, color = C.mute): React.CSSProperties => ({
  fontFamily: SANS,
  fontSize: size,
  fontWeight: weight,
  color,
  lineHeight: 1.15,
});
const over = (color = C.deep): React.CSSProperties => ({
  ...sans(30, 700, color),
  letterSpacing: "0.16em",
  textTransform: "uppercase",
});

// ───────── posição do painel ─────────
// [segundo, topo do painel]: 1920 = escondido, 840 = painel, 0 = tela cheia
const KEYS: [number, number][] = [
  [0, 1920],
  [5.2, PANEL_TOP],
  [11.15, 0],
  [16.95, 1920],
  [19.9, 0],
  [24.9, PANEL_TOP],
  [33.95, 1920],
  [35.8, 0],
  [41.5, PANEL_TOP],
  [58.8, 0],
];
const panelTopAt = (frame: number) => {
  let v = KEYS[0][1];
  for (let i = 1; i < KEYS.length; i++) {
    const p = spring({
      frame: frame - f(KEYS[i][0]),
      fps: MI_FPS,
      config: { damping: 200, mass: 0.9, stiffness: 120 },
    });
    v = v + (KEYS[i][1] - v) * p;
  }
  return v;
};

/** true = cena de motion em tela cheia (sem o médico) */
const FullCtx = React.createContext(false);

// ───────── cabeçalho de cena (posição fixa) ─────────
const Head: React.FC<{ at: number; out: number; kicker?: string; children: React.ReactNode }> = ({
  at,
  out,
  kicker,
  children,
}) => {
  const full = React.useContext(FullCtx);
  return (
    <div style={{ position: "absolute", left: 90, top: full ? 440 : 884, width: 900 }}>
      {kicker ? (
        <Reveal at={at} out={out} style={{ marginBottom: full ? 14 : 6 }}>
          <div style={{ ...over(), fontSize: full ? 42 : 30 }}>{kicker}</div>
        </Reveal>
      ) : null}
      <Reveal at={at + 0.08} out={out}>
        <div style={serif(full ? 128 : kicker ? 66 : 74)}>{children}</div>
      </Reveal>
    </div>
  );
};

// área do diagrama: 900 x 330 a partir de y=1020
const Stage: React.FC<{ out: number; children: React.ReactNode; top?: number; h?: number }> = ({
  out,
  children,
  top = 1030,
  h = 320,
}) => {
  const o = useOut(out);
  const full = React.useContext(FullCtx);
  return (
    <div
      style={{
        position: "absolute",
        left: 90,
        top: full ? 890 : top,
        width: 900,
        height: h,
        opacity: o,
        transform: full ? "scale(1.12)" : undefined,
        transformOrigin: "50% 0%",
      }}
    >
      {children}
    </div>
  );
};

const Pop: React.FC<{ at: number; style?: React.CSSProperties; children: React.ReactNode }> = ({
  at,
  style,
  children,
}) => {
  const p = useSp(at, 16, 0.6);
  const o = useRamp(at, at + 0.15);
  return (
    <div style={{ ...style, opacity: o, transform: `${style?.transform ?? ""} scale(${0.86 + 0.14 * p})` }}>
      {children}
    </div>
  );
};

const card: React.CSSProperties = {
  background: C.white,
  borderRadius: 34,
  boxShadow: "0 10px 30px rgba(47,111,174,0.12)",
  border: `2px solid ${C.line}`,
};

const Gate: React.FC<{ a: number; b: number; children: React.ReactNode }> = ({ a, b, children }) => {
  const frame = useCurrentFrame();
  return frame >= f(a) && frame <= f(b) ? <>{children}</> : null;
};

// ═════════ foto de banco ocupando a metade de baixo ═════════
const Foto: React.FC<{ src: string; at: number; pos?: string; left?: number; width?: number }> = ({
  src,
  at,
  pos = "50% 50%",
  left = 0,
  width = 1080,
}) => {
  const frame = useCurrentFrame();
  const p = useSp(at, 200, 0.9);
  const z = 1.04 + 0.05 * interpolate(frame - f(at), [0, 240], [0, 1], clamp);
  return (
    <div
      style={{
        position: "absolute",
        left,
        top: PANEL_TOP,
        width,
        height: 960,
        overflow: "hidden",
        clipPath: `inset(${(1 - p) * 100}% 0 0 0)`,
      }}
    >
      <Img
        src={staticFile(src)}
        style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${z})` }}
      />
    </div>
  );
};
const Sombra: React.FC = () => (
  <div
    style={{
      position: "absolute",
      left: 0,
      top: 1320,
      width: 1080,
      height: 600,
      background: "linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.45) 45%, rgba(0,0,0,0.55) 100%)",
    }}
  />
);
/** quadro branco com texto, no canto de cima da foto */
const Quadro: React.FC<{
  at: number;
  out: number;
  top: number;
  kicker?: string;
  dark?: boolean;
  children: React.ReactNode;
}> = ({ at, out, top, kicker, dark, children }) => {
  const frame = useCurrentFrame();
  const p = useSp(at, 20, 0.7);
  const o = useOut(out);
  if (frame < f(at)) return null;
  return (
    <div
      style={{
        position: "absolute",
        left: 70,
        top,
        padding: "26px 40px 30px",
        borderRadius: 30,
        background: dark ? C.deep : "rgba(255,255,255,0.96)",
        boxShadow: "0 14px 40px rgba(10,25,45,0.28)",
        opacity: o * Math.min(1, p * 2),
        transform: `translateY(${(1 - p) * 40}px)`,
      }}
    >
      {kicker ? <div style={{ ...over(dark ? "#CFE3F5" : C.deep), fontSize: 28, marginBottom: 6 }}>{kicker}</div> : null}
      <div style={{ ...serif(70), color: dark ? C.white : C.navy, whiteSpace: "nowrap" }}>{children}</div>
    </div>
  );
};

// ═════════ CENA C — gordura abdominal → responde pior (tela dividida) ═════════
const SceneGordura: React.FC = () => {
  const out = 11.05;
  return (
    <>
      <Foto src="medico/px/cintura1.jpg" at={5.3} pos="50% 40%" />
      <Sombra />
      <Quadro at={5.7} out={out} top={1010} kicker="Quando você acumula">
        gordura abdominal
      </Quadro>
      <Quadro at={9.3} out={out} top={1226} kicker="O corpo pode" dark>
        responder pior à insulina
      </Quadro>
    </>
  );
};

// ═════════ CENA D — insulina leva a glicose do sangue à célula ═════════
const DOTS = [
  [70, 70, 620, 110],
  [150, 120, 700, 90],
  [90, 180, 760, 130],
  [200, 60, 650, 180],
  [220, 200, 730, 200],
  [130, 240, 690, 150],
];
const SceneInsulina: React.FC = () => {
  const frame = useCurrentFrame();
  const out = 16.9;
  const door = useRamp(14.2, 14.75);
  const key = useSp(13.1, 200);
  const full = React.useContext(FullCtx);
  return (
    <>
      <Head at={11.3} out={out} kicker="O que é">
        insulina?
      </Head>
      <Reveal
        at={12.95}
        out={out}
        style={{ position: "absolute", left: full ? 90 : 470, top: full ? 660 : 946, width: full ? 900 : 520 }}
      >
        <div style={{ ...serif(full ? 96 : 46, true), color: C.deep }}>um hormônio</div>
      </Reveal>
      <Stage out={out} top={1040} h={300}>
        <svg width={900} height={300} viewBox="0 0 900 300">
          {/* sangue */}
          <rect x={0} y={20} width={320} height={260} rx={46} fill={C.white} stroke={C.line} strokeWidth={3} />
          {/* célula */}
          <circle cx={700} cy={150} r={132} fill={C.white} stroke={C.blue} strokeWidth={8} />
          {/* porta da célula */}
          <rect x={556} y={110} width={26} height={80} fill={C.bg} />
          <rect
            x={560}
            y={112}
            width={12}
            height={76}
            rx={6}
            fill={C.deep}
            transform={`rotate(${-72 * door} 566 112)`}
          />
          {/* insulina (chave) */}
          <g transform={`translate(${440 + 60 * key}, ${150})`} opacity={key}>
            <circle cx={0} cy={0} r={22} fill="none" stroke={C.deep} strokeWidth={9} />
            <line x1={22} y1={0} x2={58} y2={0} stroke={C.deep} strokeWidth={9} strokeLinecap="round" />
            <line x1={46} y1={0} x2={46} y2={14} stroke={C.deep} strokeWidth={8} strokeLinecap="round" />
          </g>
          {/* glicose */}
          {DOTS.map(([x0, y0, x1, y1], i) => {
            const appear = interpolate(frame, [f(11.6 + i * 0.08), f(11.9 + i * 0.08)], [0, 1], clamp);
            const t = interpolate(frame, [f(14.8 + i * 0.18), f(15.6 + i * 0.18)], [0, 1], {
              ...clamp,
              easing: Easing.inOut(Easing.cubic),
            });
            const midX = 540;
            const midY = 150;
            const a = Math.min(1, t * 2);
            const b = Math.max(0, t * 2 - 1);
            const x = x0 + (midX - x0) * a + (x1 - midX) * b;
            const y = y0 + (midY - y0) * a + (y1 - midY) * b + Math.sin(frame / 14 + i) * 4;
            return <circle key={i} cx={x} cy={y} r={17 * appear} fill={C.warm} stroke={C.white} strokeWidth={4} />;
          })}
        </svg>
        <div style={{ position: "absolute", left: 0, top: -6, width: 320, textAlign: "center" }}>
          <span style={{ ...sans(28, 700, C.deep), background: C.bg, padding: "2px 16px" }}>SANGUE</span>
        </div>
        <div style={{ position: "absolute", left: 568, top: -6, width: 264, textAlign: "center" }}>
          <span style={{ ...sans(28, 700, C.deep), background: C.bg, padding: "2px 16px" }}>CÉLULA</span>
        </div>
        <Pop at={14.8} style={{ position: "absolute", left: 330, top: 214, width: 220, textAlign: "center" }}>
          <span style={sans(30, 700, "#B77A1F")}>● glicose</span>
        </Pop>
        <Pop at={13.2} style={{ position: "absolute", left: 384, top: 60, width: 200, textAlign: "center" }}>
          <span style={sans(30, 700, C.deep)}>insulina</span>
        </Pop>
      </Stage>
    </>
  );
};

// ═════════ CENA E — pâncreas produz cada vez mais ═════════
const ScenePancreas: React.FC = () => {
  const frame = useCurrentFrame();
  const out = 24.8;
  const hs = [70, 115, 160, 205, 250];
  return (
    <>
      <Head at={20.15} out={out} kicker="O pâncreas precisa produzir">
        cada vez mais insulina
      </Head>
      <Stage out={out} top={1060} h={280}>
        <svg width={900} height={280} viewBox="0 0 900 280">
          <line x1={0} y1={268} x2={520} y2={268} stroke={C.line} strokeWidth={6} strokeLinecap="round" />
          {hs.map((h, i) => {
            const p = spring({
              frame: frame - f(20.9 + i * 0.36),
              fps: MI_FPS,
              config: { damping: 18, mass: 0.6, stiffness: 150 },
            });
            return (
              <rect
                key={i}
                x={20 + i * 100}
                y={264 - h * p}
                width={72}
                height={h * p}
                rx={16}
                fill={i === 4 ? C.deep : C.blue}
                opacity={0.45 + i * 0.14}
              />
            );
          })}
        </svg>
        <Pop
          at={23.1}
          style={{
            ...card,
            position: "absolute",
            left: 560,
            top: 50,
            width: 340,
            height: 190,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            padding: "0 32px",
          }}
        >
          <div style={{ ...sans(30, 500), marginBottom: 6 }}>para fazer o</div>
          <div style={serif(52, true)}>mesmo trabalho</div>
        </Pop>
      </Stage>
    </>
  );
};

// ═════════ CENA F — no começo: glicose normal, insulina alta ═════════
const Row: React.FC<{ at: number; top: number; label: string; children: React.ReactNode }> = ({
  at,
  top,
  label,
  children,
}) => {
  const p = useSp(at);
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        top,
        width: 900,
        height: 92,
        opacity: p,
        transform: `translateX(${(1 - p) * -40}px)`,
        display: "flex",
        alignItems: "center",
      }}
    >
      <div style={{ width: 230, ...sans(40, 700, C.navy) }}>{label}</div>
      <div style={{ position: "relative", flex: 1, height: 92 }}>{children}</div>
    </div>
  );
};
const SceneComeco: React.FC = () => {
  const frame = useCurrentFrame();
  const out = 33.9;
  const marker = useSp(27.7, 14, 0.8);
  const steps = [31.75, 32.35, 32.87, 33.25];
  const levels = [0.4, 0.6, 0.8, 1];
  let fill = 0;
  steps.forEach((s, i) => {
    const p = spring({ frame: frame - f(s), fps: MI_FPS, config: { damping: 13, mass: 0.5, stiffness: 180 } });
    fill = fill + (levels[i] - fill) * p;
  });
  return (
    <>
      <Head at={25.05} out={out}>
        No começo
      </Head>
      <Stage out={out} top={1000} h={340}>
        <Row at={25.6} top={0} label="Pâncreas">
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 14,
              height: 64,
              padding: "0 30px",
              borderRadius: 32,
              background: C.white,
              border: `2px solid ${C.line}`,
              display: "flex",
              alignItems: "center",
              gap: 16,
            }}
          >
            <svg width={36} height={36} viewBox="0 0 36 36">
              <circle cx={18} cy={18} r={18} fill={C.blue} />
              <path d="M9 18 L16 25 L27 12" fill="none" stroke="#fff" strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            <span style={sans(36, 700, C.navy)}>consegue compensar</span>
          </div>
        </Row>
        <Row at={27.3} top={112} label="Glicose">
          <div style={{ position: "absolute", left: 0, top: 34, width: 290, height: 24, borderRadius: 12, background: C.white, border: `2px solid ${C.line}` }} />
          <div style={{ position: "absolute", left: 0, top: 34, width: 190, height: 24, borderRadius: 12, background: C.blue, opacity: 0.35 }} />
          <div
            style={{
              position: "absolute",
              left: 10 + 90 * marker,
              top: 22,
              width: 48,
              height: 48,
              borderRadius: 24,
              background: C.deep,
              border: "6px solid #fff",
              boxSizing: "border-box",
              boxShadow: "0 4px 12px rgba(22,50,79,.25)",
            }}
          />
          <Pop at={28.3} style={{ position: "absolute", left: 316, top: 20, whiteSpace: "nowrap" }}>
            <span style={{ ...serif(42, true), color: C.deep }}>pode ficar normal</span>
          </Pop>
        </Row>
        <Row at={31.2} top={224} label="Insulina">
          <div style={{ position: "absolute", left: 0, top: 20, width: 670, height: 52, borderRadius: 26, background: C.white, border: `2px solid ${C.line}`, overflow: "hidden" }}>
            <div style={{ width: `${fill * 100}%`, height: "100%", borderRadius: 26, background: `linear-gradient(90deg, ${C.blue}, ${C.deep})` }} />
          </div>
          <Pop at={32.35} style={{ position: "absolute", left: 24, top: 24 }}>
            <span style={sans(36, 700, C.white)}>muita insulina</span>
          </Pop>
        </Row>
      </Stage>
    </>
  );
};

// ═════════ CENA H — evolução ═════════
const PTS = [
  { x: 190, y: 232, at: 36.9, label: "Glicose sobe" },
  { x: 490, y: 176, at: 38.2, label: "Pré-diabetes" },
  { x: 800, y: 110, at: 39.95, label: "Diabetes tipo 2" },
];
const SceneEvolucao: React.FC = () => {
  const frame = useCurrentFrame();
  const out = 48.3;
  const draw = interpolate(frame, [f(36.0), f(36.9), f(38.2), f(39.95)], [0, 0.26, 0.6, 0.95], clamp);
  const LEN = 900;
  const pinMove = useSp(45.5, 200, 1);
  const pinIn = useSp(41.7, 14, 0.7);
  const pinX = 800 + (36 - 800) * pinMove;
  const pinY = 110 + (252 - 110) * pinMove;
  const pulse = 1 + 0.12 * Math.sin(frame / 5);
  return (
    <>
      <Head at={36.0} out={41.45} kicker="Com o tempo">
        a evolução
      </Head>
      <Head at={41.65} out={45.35} kicker="É aqui que muita gente">
        começa a tratar
      </Head>
      <Head at={45.5} out={out} kicker="Faz total diferença">
        tratar desde o começo
      </Head>
      <Stage out={out} top={1050} h={300}>
        <svg width={900} height={300} viewBox="0 0 900 300" style={{ overflow: "visible" }}>
          <line x1={20} y1={272} x2={880} y2={272} stroke={C.line} strokeWidth={5} strokeLinecap="round" />
          <path
            d="M36 252 C 120 250, 150 240, 190 232 S 400 206, 490 176 S 700 140, 800 110 L 866 90"
            fill="none"
            stroke={C.blue}
            strokeWidth={10}
            strokeLinecap="round"
            strokeDasharray={`${draw * LEN} ${LEN}`}
          />
          {PTS.map((p, i) => {
            const s = spring({ frame: frame - f(p.at), fps: MI_FPS, config: { damping: 14, mass: 0.6 } });
            return <circle key={i} cx={p.x} cy={p.y} r={17 * s} fill={C.white} stroke={C.deep} strokeWidth={8} />;
          })}
          <circle cx={36} cy={252} r={12} fill={C.deep} />
          <circle
            cx={pinX}
            cy={pinY}
            r={38 * pinIn * pulse}
            fill="none"
            stroke={C.warm}
            strokeWidth={8}
          />
        </svg>
        {PTS.map((p, i) => (
          <Pop
            key={i}
            at={p.at + 0.05}
            style={{
              position: "absolute",
              left: p.x - 200 + (i === 2 ? -60 : 0),
              top: p.y - 84,
              width: 400,
              textAlign: "center",
            }}
          >
            <span style={{ ...sans(34, 700, C.navy), background: C.bg, padding: "2px 12px", borderRadius: 10 }}>{p.label}</span>
          </Pop>
        ))}
      </Stage>
    </>
  );
};

// ═════════ CENA J — o que pode reduzir o risco (tela dividida) ═════════
const SceneRisco: React.FC = () => {
  const out = 55.8;
  return (
    <>
      <Foto src="medico/px/balanca1.jpg" at={48.4} />
      <Gate a={49.4} b={99}>
        <Foto src="medico/px/caminhada1.jpg" at={49.4} pos="40% 60%" />
      </Gate>
      <Gate a={50.55} b={99}>
        <Foto src="medico/px/consulta2.jpg" at={50.55} pos="60% 50%" />
      </Gate>
      <Gate a={54.3} b={99}>
        <Foto src="medico/px/balanca1.jpg" at={54.3} left={0} width={356} />
        <Foto src="medico/px/caminhada1.jpg" at={54.4} left={362} width={356} pos="42% 60%" />
        <Foto src="medico/px/consulta2.jpg" at={54.5} left={724} width={356} pos="70% 50%" />
      </Gate>
      <Sombra />
      <Quadro at={48.55} out={49.4} top={1010}>
        Perder peso
      </Quadro>
      <Quadro at={49.5} out={50.55} top={1010}>
        Atividade física
      </Quadro>
      <Quadro at={50.7} out={54.3} top={1010} kicker="Quando indicado">
