// ═════════ legendas ═════════
const HIDE: [number, number][] = [
  [0, 5.3],
  [33.95, 35.9],
  [55.9, 99],
];
const Legenda: React.FC<{ panelTop: number }> = ({ panelTop }) => {
  const frame = useCurrentFrame();
  const t = frame / MI_FPS;
  if (HIDE.some(([a, b]) => t >= a && t < b)) return null;
  const cap = CAPS.find(([a, b]) => t >= a && t < b);
  if (!cap) return null;
  const p = interpolate(frame - f(cap[0]), [0, 4], [0, 1], clamp);
  const naFoto = (t >= 5.3 && t < 11.1) || (t >= 48.4 && t < 55.9);
  const claro = naFoto || panelTop >= 1490;
  return (
    <div
      style={{
        position: "absolute",
        left: 90,
        width: 900,
        top: panelTop < 200 ? 1330 : 1500,
        textAlign: "center",
        ...sans(60, 700, claro ? "#FFFFFF" : C.navy),
        textShadow: claro ? "0 2px 16px rgba(0,0,0,0.5)" : "none",
        opacity: p,
        transform: `translateY(${(1 - p) * 10}px)`,
      }}
    >
      {cap[2]}
    </div>
  );
};

